package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

var TempRecCurrent TempRec

var tempFileScanner *bufio.Scanner
var tempFile *os.File

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func formatZZ9_9(v decimal.Decimal) string {
	// PIC ZZ9.9 len 5
	return formatNumericEdited(v, 3, 1, false, false, 5)
}
func formatMinusZZ9_99(v decimal.Decimal) string {
	// PIC -ZZ9.99 len 7 : fixed leading minus sign? spec says fixed leading minus sign.
	// That means always show sign: '-' for negative, ' ' for positive? But picture is "-ZZ9.99"
	// In COBOL, leading '-' floats? Actually "-" as first char means fixed minus sign: show '-' if negative else space.
	return formatNumericEdited(v, 3, 2, true, true, 7)
}

// generic formatter for numeric-edited
func formatNumericEdited(v decimal.Decimal, intDigits int, decDigits int, signed bool, fixedSign bool, width int) string {
	// v may be negative
	neg := v.Sign() < 0
	absVal := v.Abs()

	// Truncate/round already done by storage, but format must handle decimal part
	// Represent absVal scaled to decDigits
	// Use string of absVal with exactly decDigits fractional digits
	// absVal may have more fractional than needed due to dec truncation; ensure truncated to decDigits
	// But WS fields already truncated/rounded to their scale. So just format.

	// Get integer and fractional parts
	// Use Abs string
	// We can get integer part by truncating
	shifted := absVal.Shift(int32(decDigits)) // *10^dec
	// shifted should be integer (maybe)
	shifted = shifted.Truncate(0)
	intPart := shifted.Div(decimal.NewFromInt(1).Shift(int32(decDigits))).Truncate(0)
	// Alternatively get via Pow
	// simpler: format using string
	// compute integer value as int64 (may overflow but picture small)
	intVal := shifted.IntPart() // this is actually scaled integer
	// intPart digits: intVal / 10^decDigits
	pow := int64(1)
	for i := 0; i < decDigits; i++ {
		pow *= 10
	}
	fracVal := intVal % pow
	intDigitsVal := intVal / pow

	// Build integer field string of length intDigits (e.g., 3 for ZZ9)
	// Pictures: Z replaces leading zero with space, 9 always digit
	// For "-ZZ9.99": the sign is an extra leading character (width = 1 + intDigits + 1 + decDigits)
	// For non-signed, width = intDigits + 1 + decDigits

	// Handle overflow: keep low-order digits
	mod := int64(1)
	for i := 0; i < intDigits; i++ {
		mod *= 10
	}
	intDigitsVal = intDigitsVal % mod

	// Format integer part with zero padding to intDigits
	intStr := fmt.Sprintf("%0*d", intDigits, intDigitsVal)

	// Apply Z suppression: replace leading zeros with spaces until last digit before 9
	// For pattern ZZ9, the last char is always 9, preceding are Z.
	// So find first non-space? General: number of Z = intDigits-1, last is 9
	// Convert leading zeros to spaces, but commas inside suppressed zone also spaces (no comma here)
	zCount := intDigits - 1
	for i := 0; i < zCount; i++ {
		if intStr[i] == '0' {
			// check if all remaining up to? Actually Z suppression: if the digit is zero and all more significant are suppressed/spaces/zeros, then space
			// For simple ZZ9, we can check if the prefix up to i is all zeros
			allZero := true
			for k := 0; k <= i; k++ {
				if intStr[k] != '0' {
					allZero = false
					break
				}
			}
			// But also if integer is zero, we want "  0"
			// So we should replace until we hit non-zero from left, but leave at least the last '9' position
			// Actually for ZZ9, "000" -> "  0", "010" -> " 10", "100" -> "100"
			// So we replace leading zeros with spaces as long as we are in Z positions and the remaining prefix has no non-zero?
			// Simpler: iterate from left, if we have seen non-zero then keep digit, else if digit == '0' and we are in Z area then space, but need to handle "001" -> "  1" (works)
			// Check if any non-zero earlier in intStr before current? we already would have broken
			// So just if the prefix up to intDigits-1 except last? Let's implement generic
			// If intStr[i]=='0' and no non-zero before (including later? not) then space unless it's the final 9 position
			// For ZZ9, if intStr = "001", i=0 -> zero and no non-zero before -> space, i=1 -> zero but next char is 1? Actually we are at i=1, prefix "00" all zeros -> but there is non-zero later (at position 2). Should we still space? Yes, suppress.
			// So condition is intStr[i]=='0' and all digits from 0..i are zero? No need to look ahead.
			// Actually "010" -> expect " 10": i0=0 -> space, i1=1 -> non-zero -> keep.
			// So rule: replace leading zeros in Z positions with spaces until first non-zero encountered.
			// Implement that:
			// We'll do a pass: foundNonZero = false
			// for i 0..zCount-1: if !foundNonZero && intStr[i]=='0' -> space else foundNonZero=true
		} else {
			break
		}
	}
	// Implement precisely:
	chars := []byte(intStr)
	foundNonZero := false
	for i := 0; i < zCount; i++ {
		if !foundNonZero && chars[i] == '0' {
			chars[i] = ' '
		} else {
			foundNonZero = true
		}
	}
	intStr = string(chars)

	fracStr := fmt.Sprintf("%0*d", decDigits, fracVal)

	var body string
	if decDigits > 0 {
		body = intStr + "." + fracStr
	} else {
		body = intStr
	}

	if signed {
		// fixed leading minus sign: width includes sign
		// sign char at position 0
		signChar := byte(' ')
		if neg {
			signChar = '-'
		}
		// body is intDigits+1+decDigits, total width = 1+len(body)
		// For "-ZZ9.99", intDigits=3, body len=6, width=7 OK
		return string(signChar) + body
	} else {
		return body
	}
}

func formatPIC99(v int64) string {
	// PIC 99 -> zero padded 2 digits, overflow keep low-order
	mod := int64(100)
	v = v % mod
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v)
}

func storeWsC(v decimal.Decimal) {
	// PIC S9(3)V99 : scale 2, int digits 3, signed
	// Truncate toward zero to 2 decimals, then keep low-order integer digits
	// COBOL storing keeps low-order digits; we implement overflow
	v = v.Truncate(2)
	neg := v.Sign() < 0
	abs := v.Abs()
	// keep low order int digits
	// scaled integer
	scaled := abs.Shift(2).Truncate(0) // *100
	// mod for integer overflow: 10^(3+2)=100000
	mod := decimal.NewFromInt(100000)
	// low-order 5 digits
	low := scaled.Mod(mod)
	if neg {
		low = low.Neg()
	}
	WsC = low.Shift(-2)
}

func main() {
	// OPEN INPUT TEMP-FILE
	var err error
	tempFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer tempFile.Close()
	tempFileScanner = bufio.NewScanner(tempFile)
	// COBOL LINE SEQUENTIAL - preserve spaces? Scanner strips newline but keeps other spaces
	// Need to handle lines shorter than 8 padded with spaces

	MAIN_PARA()
}

func MAIN_PARA() {
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE already deferred
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	// WS-COUNT and WS-FREEZE are PIC 99 edited as zero-padded
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPIC99(WsCount), formatPIC99(WsFreeze))
}

func READ_PARA() {
	if !tempFileScanner.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := tempFileScanner.Text()
	// pad with spaces on right to 8
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	// parse
	tcSensor := line[0:4]
	tcFRaw := line[4:8]
	// TC-F PIC 9(3)V9 : 4 digits implied 1 decimal
	n := int64(0)
	for _, ch := range tcFRaw {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		} else {
			// space treated as 0? but spec says digits only
			n = n * 10
		}
	}
	tcF := decimal.New(n, -1)
	TempRecCurrent = TempRec{
		TcSensor: tcSensor,
		TcF:      tcF,
	}
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	diff := TempRecCurrent.TcF.Sub(decimal.NewFromInt(32))
	mult := diff.Mul(decimal.NewFromInt(5))
	// divide by 9 with high precision then round
	// Use decimal division then Round(2)
	quot := mult.Div(decimal.NewFromInt(9))
	rounded := quot.Round(2)
	storeWsC(rounded)

	if WsC.Sign() < 0 {
		WsFreeze = WsFreeze + 1
		// overflow for PIC 99 keep low 2 digits
		WsFreeze = WsFreeze % 100
	}
	WsCount = WsCount + 1
	WsCount = WsCount % 100

	WsFEd = formatZZ9_9(TempRecCurrent.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	fmt.Printf("%s %sF %sC\n", TempRecCurrent.TcSensor, WsFEd, WsCEd)
	READ_PARA()
}

